const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length);
const q = Number(tok[0]);
const BASES = [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n];
function gcd(a, b) { while (b) { [a, b] = [b, a % b]; } return a; }
function powmod(b, e, m) {
  let r = 1n; b %= m;
  while (e > 0n) { if (e & 1n) r = r * b % m; b = b * b % m; e >>= 1n; }
  return r;
}
function isPrime(n) {
  if (n < 2n) return false;
  for (const p of BASES) if (n % p === 0n) return n === p;
  let d = n - 1n, s = 0;
  while (d % 2n === 0n) { d /= 2n; s++; }
  for (const a of BASES) {
    let x = powmod(a, d, n);
    if (x === 1n || x === n - 1n) continue;
    let composite = true;
    for (let i = 0; i < s - 1; i++) {
      x = x * x % n;
      if (x === n - 1n) { composite = false; break; }
    }
    if (composite) return false;
  }
  return true;
}
function abs(a) { return a < 0n ? -a : a; }
function pollardRho(n) {
  let c = 1n;
  for (;;) {
    let x = 2n, y = 2n, g = 1n;
    while (g === 1n) {
      const xs = x, ys = y;
      let prod = 1n;
      for (let i = 0; i < 64; i++) {
        x = (x * x + c) % n;
        y = (y * y + c) % n;
        y = (y * y + c) % n;
        prod = prod * abs(x - y) % n;
      }
      g = gcd(prod, n);
      if (g === n) {
        x = xs; y = ys; g = 1n;
        while (g === 1n) {
          x = (x * x + c) % n;
          y = (y * y + c) % n;
          y = (y * y + c) % n;
          g = gcd(abs(x - y), n);
        }
        break;
      }
    }
    if (g !== n) return g;
    c += 1n;
  }
}
function factor(n, counts) {
  if (n === 1n) return;
  if (isPrime(n)) { const k = n.toString(); counts.set(k, (counts.get(k) || 0) + 1); return; }
  const d = pollardRho(n);
  factor(d, counts);
  factor(n / d, counts);
